    @Test
    public void testIsAvailableLocale_WithNull() {
        // Testing behavior with null. 
        // Based on the implementation 'cAvailableLocaleSet.contains(locale)', 
        // if the set implementation (like HashSet) allows null, it returns false.
        // If the set is a specialized collection, it might throw NPE.
        // This test covers the branch/line for a null input.
        try {
            boolean result = LocaleUtils.isAvailableLocale(null);
            assertFalse("Expected false when checking null locale", result);
        } catch (NullPointerException e) {
            // If the internal set implementation does not allow null, 
            // the method effectively fails on null, which is acceptable behavior 
            // depending on the internal set's contract.
        }
    }


