import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.isAvailableLocale
 */
public class LocaleUtils_isAvailableLocale_TriageGen5Test {







    @Test
    public void testIsAvailableLocale_WithDifferentLocaleInstances() {
        // Test that different instances representing the same locale return true
        Locale locale1 = Locale.US;
        Locale locale2 = new Locale("en", "US");

        // Check if US is available via the list first to be sure
        if (LocaleUtils.isAvailableLocale(locale1)) {
            assertTrue("Expected true for Locale.US", LocaleUtils.isAvailableLocale(locale1));
            assertTrue("Expected true for new Locale('en', 'US')", LocaleUtils.isAvailableLocale(locale2));
        }
    }
}
